import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns customer invoices with outstanding balance', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);

  const result = statement('C-001', [result2.value], '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
  assert.equal(result.value.invoices[0].dueDate, '2026-11-06');
  assert.equal(typeof result.value.invoices[0].total, 'number');
  assert.equal(typeof result.value.invoices[0].due, 'number');
});

test('statement calculates totalDue correctly', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);

  const result = statement('C-001', [result2.value], '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.totalDue, result.value.invoices[0].due);
});

test('statement normalizes customer ID', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);

  const result = statement('c-001', [result2.value], '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('statement rejects unknown customer', () => {
  const result = statement('C-999', [], '2026-10-10');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement excludes invoices after asOf date', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);

  const result = statement('C-001', [result2.value], '2026-10-06');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement includes invoices on asOf date', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);

  const result = statement('C-001', [result2.value], '2026-10-07');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes draft invoices', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result = statement('C-001', [result1.value], '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes paid invoices', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);
  const result3 = recordPayment(result2.value, { amount: 109202, date: '2026-10-10' });

  const result = statement('C-001', [result3.value], '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, 0);
});

test('statement excludes invoices for other customers', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result3 = issueInvoice(result1.value, []);
  const result4 = issueInvoice(result2.value, ['INV-2026-0001']);

  const result = statement('C-001', [result3.value, result4.value], '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement sorts invoices by issueDate', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  const result4 = issueInvoice(result1.value, []);
  const result5 = issueInvoice(result2.value, ['INV-2026-0001']);
  const result6 = issueInvoice(result3.value, ['INV-2026-0001', 'INV-2026-0002']);

  const result = statement('C-001', [result4.value, result5.value, result6.value], '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-10');
  assert.equal(result.value.invoices[2].issueDate, '2026-10-15');
});

test('statement sums totalDue correctly with multiple invoices', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result3 = issueInvoice(result1.value, []);
  const result4 = issueInvoice(result2.value, ['INV-2026-0001']);

  const result = statement('C-001', [result3.value, result4.value], '2026-10-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.totalDue, result.value.invoices[0].due + result.value.invoices[1].due);
});

test('statement calculates due correctly with partial payments', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);
  const result3 = recordPayment(result2.value, { amount: 50000, date: '2026-10-10' });

  const result = statement('C-001', [result3.value], '2026-10-15');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].due, 59202);
});

test('statement calculates total from invoiceTotals', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const result2 = issueInvoice(result1.value, []);

  const result = statement('C-001', [result2.value], '2026-10-10');

