test('statement with multiple customers mixed in invoices list', () => {
  const invoices = [];

  for (let i = 1; i <= 3; i++) {
    const result1 = createInvoice({
      customerId: `C-00${i}`,
      issueDate: '2026-10-07',
      lines: [{ sku: 'DEV-HOUR', qty: i * 5 }],
    });

    const result2 = issueInvoice(result1.value, []);
    invoices.push(result2.value);
  }

  const result = statement('C-002', invoices, '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0002');
});
